function get_stats_data() {
    $load = sys_getloadavg();

    $mem_info = shell_exec("free -m | grep Mem");
    $mem_percent = 0;

    if ($mem_info) {
        preg_match_all('/\d+/', $mem_info, $matches);

        if (count($matches[0]) >= 2) {
            $mem_percent = round(($matches[0][1] / $matches[0][0]) * 100);
        }
    }

    $disk_total = disk_total_space("/");
    $disk_free  = disk_free_space("/");
    $disk_used  = $disk_total - $disk_free;

    $disk_percent = round(($disk_used / $disk_total) * 100);

    return [
        'cpu'  => number_format($load[0], 2),
        'mem'  => $mem_percent,
        'disk' => $disk_percent
    ];
}

function get_system_static() {
    return [
        'kernel' => php_uname('s') . " " . php_uname('r') . " " . php_uname('m'),
        'uptime' => trim(shell_exec('uptime -p') ?: 'N/A')
    ];
}

