function playIntroAnimation(onComplete) {

    const anim = document.getElementById('ascii-animation');
    const intro = document.getElementById('intro-container');
    const term = document.getElementById('terminal');

    intro.style.display = 'flex';
    // Force reflow
    void intro.offsetWidth;
    intro.style.opacity = '1';

    // Randomly select animation (0 or 1)
    const animChoice = Math.floor(Math.random() * 2);
    
    // Set font size based on animation choice
    if (animChoice === 0) {
        anim.style.fontSize = "5px";
    } else {
        anim.style.fontSize = "6px";
    }

    const frames = (animChoice === 0) ? asciiFrames : asciiFrames2;
    const loops = (animChoice === 0) ? 2 : 1;
    const totalDuration = 1000; // 1 second target

    // Wait for the 0.15s fade-in to finish before starting the animation
    setTimeout(() => {
        let fIndex = 0;
        let loopCount = 0;

        const totalFrames = frames.length;
        const intervalTime = Math.floor(totalDuration / (totalFrames * loops));

        const interval = setInterval(() => {

            anim.textContent = frames[fIndex];
            fIndex++;

            if (fIndex >= totalFrames) {
                fIndex = 0;
                loopCount++;
                
                if (loopCount >= loops) {
                    clearInterval(interval);
                    
                    // Fade out intro, Fade in terminal
                    intro.style.opacity = '0';
                    
                    setTimeout(() => {
                        intro.style.display = 'none';
                        term.style.display = 'flex';
                        // Force reflow
                        void term.offsetWidth;
                        term.style.opacity = '1';
                        onComplete();
                    }, 150);
                }
            }

        }, intervalTime);
    }, 150);
}

